<template>
  <MarketplaceLayout><main class="market-container market-page community-page"><div class="discussion">
    <RouterLink :to="id?'/community/posts/'+id:'/community'">{{ id?'Quay lại bài viết':'Về cộng đồng' }}</RouterLink><h1>{{ id?'Chỉnh sửa bài viết':'Chia sẻ với cộng đồng' }}</h1>
    <ResourceState v-if="loading || loadError" resource="bài viết" :loading="loading" :error="Boolean(loadError)" @retry="load"/>
    <form v-else @submit.prevent="save"><label for="post-title">Tiêu đề</label><input id="post-title" v-model="form.title" required maxlength="180"/><label for="post-topic">Chủ đề</label><select id="post-topic" v-model="form.topic"><option v-for="(label,key) in topics" :key="key" :value="key">{{ label }}</option></select><label for="post-body">Nội dung bài viết</label><textarea id="post-body" v-model="form.body" required maxlength="12000" rows="14"/><p class="discussion-notice">Tối đa 12.000 ký tự. Nội dung được hiển thị dưới dạng văn bản. Không chia sẻ thông tin riêng tư của bạn hoặc người khác.</p><p v-if="error" ref="errorBox" tabindex="-1" role="alert">{{ error }}</p><div class="discussion-actions"><button class="button button-primary" :disabled="busy || !form.title.trim() || !form.body.trim()">{{ busy?'Đang lưu…':id?'Lưu thay đổi':'Đăng bài' }}</button><RouterLink :to="id?'/community/posts/'+id:'/community'" class="button button-outline">Hủy</RouterLink></div></form>
  </div></main></MarketplaceLayout>
</template>
<script setup>
import {ref,reactive,computed,watch,onBeforeUnmount,nextTick} from 'vue';import {useRoute,useRouter} from 'vue-router';import MarketplaceLayout from '../../../layouts/MarketplaceLayout.vue';import ResourceState from '../../../components/marketplace/ResourceState.vue';import {marketplaceRequest as request} from '../../../services/marketplace.js';import {topics} from '../../../services/discussions.js';import '../../../css/discussions.css';
const route=useRoute(),router=useRouter(),id=computed(()=>route.params.id),loading=ref(false),loadError=ref(''),busy=ref(false),error=ref(''),errorBox=ref(null),form=reactive({title:'',body:'',topic:'CARE',revision:0});let generation=0;
async function load(){const ticket=++generation;error.value='';loadError.value='';Object.assign(form,{title:'',body:'',topic:'CARE',revision:0});if(!id.value)return;loading.value=true;try{const post=await request('/community/posts/'+encodeURIComponent(id.value));if(ticket===generation)Object.assign(form,{title:post.title,body:post.body,topic:post.topic,revision:post.revision});}catch(e){if(ticket===generation)loadError.value=e.message;}finally{if(ticket===generation)loading.value=false;}}
async function save(){if(busy.value)return;busy.value=true;error.value='';const ticket=generation;try{const post=await request('/account/community/posts'+(id.value?'/'+encodeURIComponent(id.value):''),id.value?'PUT':'POST',{...form});if(ticket===generation)await router.push('/community/posts/'+post.id);}catch(e){if(ticket===generation){error.value=e.message;await nextTick();errorBox.value?.focus();}}finally{busy.value=false;}}
watch(()=>id.value,load,{immediate:true});onBeforeUnmount(()=>generation++);
</script>
